div.script:

(function () {
    var dataEl = document.getElementById("analytics-chart-data");
    if (!dataEl || typeof window.Chart === "undefined") {
        return;
    }
    var payload = JSON.parse(dataEl.textContent || "{}");
    var palette = ["#0d6efd", "#198754", "#6610f2", "#fd7e14", "#20c997", "#dc3545", "#0dcaf0", "#6c757d"];
    var charts = {};

    function renderTrend(chartType) {
        var ctx = document.getElementById("analyticsTrendChart");
        if (!ctx || !payload.trend) return;
        if (charts.trend) charts.trend.destroy();
        charts.trend = new Chart(ctx, {
            type: chartType || "line",
            data: {
                labels: payload.trend.labels,
                datasets: [
                    {
                        label: "Current Sales",
                        data: payload.trend.sales,
                        borderColor: "#0d6efd",
                        backgroundColor: "rgba(13,110,253,0.20)",
                        tension: 0.3,
                        fill: chartType === "line"
                    },
                    {
                        label: "Previous Period Sales",
                        data: payload.trend.prev_sales,
                        borderColor: "#6c757d",
                        backgroundColor: "rgba(108,117,125,0.20)",
                        borderDash: [5, 5],
                        tension: 0.3
                    },
                    {
                        label: "Purchase Spend",
                        data: payload.trend.purchase,
                        borderColor: "#fd7e14",
                        backgroundColor: "rgba(253,126,20,0.25)",
                        tension: 0.3
                    }
                ]
            },
            options: { responsive: true, maintainAspectRatio: false }
        });
    }

    function renderModuleCompare() {
        var ctx = document.getElementById("analyticsModuleChart");
        if (!ctx || !payload.modules) return;
        charts.modules = new Chart(ctx, {
            type: "bar",
            data: {
                labels: payload.modules.labels,
                datasets: [{
                    label: payload.currency || "Amount",
                    data: payload.modules.current,
                    backgroundColor: palette
                }]
            },
            options: {
                indexAxis: "y",
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } }
            }
        });
    }

    function renderChannel(chartType) {
        var ctx = document.getElementById("analyticsChannelChart");
        if (!ctx || !payload.channels) return;
        if (charts.channel) charts.channel.destroy();
        charts.channel = new Chart(ctx, {
            type: chartType || "bar",
            data: {
                labels: payload.channels.labels,
                datasets: [{
                    label: "Revenue",
                    data: payload.channels.revenue,
                    backgroundColor: palette
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: chartType === "doughnut" } }
            }
        });
    }

    function renderPayment() {
        var ctx = document.getElementById("analyticsPaymentChart");
        if (!ctx || !payload.payment_mix) return;
        charts.payment = new Chart(ctx, {
            type: "doughnut",
            data: {
                labels: payload.payment_mix.labels,
                datasets: [{
                    data: payload.payment_mix.values,
                    backgroundColor: ["#198754", "#ffc107", "#dc3545"]
                }]
            },
            options: { responsive: true, maintainAspectRatio: false }
        });
    }

    function renderCustomers() {
        var ctx = document.getElementById("analyticsCustomerChart");
        if (!ctx || !payload.customers) return;
        charts.customers = new Chart(ctx, {
            type: "bar",
            data: {
                labels: payload.customers.labels,
                datasets: [{
                    label: "Revenue",
                    data: payload.customers.revenue,
                    backgroundColor: "#6610f2"
                }]
            },
            options: {
                indexAxis: "y",
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } }
            }
        });
    }

    renderTrend("line");
    renderModuleCompare();
    renderChannel("bar");
    renderPayment();
    renderCustomers();

    document.querySelectorAll("[data-chart-switch]").forEach(function (btn) {
        btn.addEventListener("click", function () {
            var parts = btn.getAttribute("data-chart-switch").split(":");
            var group = btn.closest(".btn-group");
            if (group) {
                group.querySelectorAll("button").forEach(function (b) { b.classList.remove("active"); });
            }
            btn.classList.add("active");
            if (parts[0] === "trend") renderTrend(parts[1]);
            if (parts[0] === "channel") renderChannel(parts[1]);
        });
    });
})();
